; CYCLES_FORWARD_BRANCHES
; AERIA ECHO (2nd version) -- Chloaelis' dual delay (DSP.h DelayCell), hard panned, dual mono. Generated by echo2/gen.py.
; left in -> left line (Y ring, 16384 words at the buffer base) -> left out; right in -> right line (X ring, 16384
; words at X:$10000) -> right out. Lines hold (in + regen)/2. Delays 16376 samples at most (371.3 ms).
;  knob 0 TIME  left delay 30 .. 370 ms (log)
;  knob 1 FDBK  loop gain 0.99 v/115 (v <= 115), then up to 1.2075 at 127 (self-oscillation, held by the rider)
;  knob 2 TONE  feedback lowpass 300 Hz x 60^(v/127); 127 = open
;  knob 3 SKEW  right delay = left x 2^((v - 64)/64), held to the ring
;  knob 4 SPRD  127 = hard panned (the plugin), 0 = both sides summed
;  knob 5 MIX   0 = exact dry
;  FUNC r6+$c hi HPF  0 off (10 Hz DC blocker), else two one-pole high-passes at 0.7781 x 320 Hz x 2^((v-90)/22)
;       r6+$c lo FRZ  0 / 1 hold;  r6+$d bit 0: the ColdFire's random freeze (set = hold)
;       r6+$d hi RFRZ (ColdFire only)   r6+$d lo TMOD 0 SLEW / 1 FADE   r6+$e hi GLID 1.6 Hz x 2^((v-64)/24)
; Rider: env = peak of the filtered read (block peak, release 0.3 s); k = min(regen, 0.29 / env) (line units),
; ramped over each call. Regen is truncated toward zero (decays to exact silence below unity).

init:
        move    #>$ffffff,m4
        move    #>$ffffff,m3
        move    r7,r4
        clr     a
        do      #96,>e2izero
        move    a,x:(r4)+
e2izero:
        nop     
        move    r7,x0
        move    #>$40,a
        add     x0,a
        move    a1,r3
        move    x:>$213,r4
        move    x:(r4),a
        move    a,x:(r3+$00)
        move    a,x:(r3+$01)
        move    #>$010000,a
        move    a,x:(r3+$03)
        move    #>$80,a
        move    a,x:(r3+$02)
        rts     
proc:
        move    #>$ffffff,m4
        move    #>$ffffff,m3
        move    #>$1,n0
        move    r7,x0
        move    #>$40,a
        add     x0,a
        move    a1,r3
; FDBK -> RG = k/2 at most
        move    x:(r6+$1),x0
        move    #>$4685be,y0
        mpy     y0,x0,a
        move    x0,b
        sub     #>$730000,b
        move    #>$0,x1
        tlt     x1,b
        move    b,x0
        move    #>$7fffff,y0
        mac     y0,x0,a
        move    a,x:(r3+$05)
; TONE (127 = open)
        move    x:(r6+$2),a
        move    a,x0
        move    #>$7f0000,a
        move    #>$0,x1
        sub     x0,a
        tlt     x1,a
        move    a,x0
        move    #>$17d048,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$0eccaf,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$7fffff,a
        sub     x0,a
        move    x:(r6+$2),b
        move    #>$7f0000,x0
        cmp     x0,b
        blt     e2tset
        move    #>$7fffff,a
e2tset:
        move    a,x:(r7+$07)
; HPF (FUNC r6+$c bits 22..16): 0 = a 10 Hz DC blocker alone
        move    x:(r6+$c),a
        and     #>$7f0000,a
        tst     a
        bne     e2hpon
        move    #>$002ea7,x0
        move    x0,x:(r7+$08)
        clr     a
        move    a,x:(r7+$09)
        move    a,x:(r7+$19)
        move    a,x:(r7+$1a)
        move    a,x:(r7+$31)
        move    a,x:(r7+$32)
        bra     e2hpdone
e2hpon:
        move    a,x0
        move    #>$7f0000,a
        move    #>$0,x1
        sub     x0,a
        tlt     x1,a
        move    a,x0
        move    #>$1745d1,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$00a827,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$7fffff,a
        sub     x0,a
        move    a,x:(r7+$08)
        move    a,x:(r7+$09)
e2hpdone:
; FRZ (r6+$c bits 14..8) or the random-freeze bit (r6+$d bit 0)
        move    x:(r6+$d),b
        and     #>$000001,b
        move    b1,x0
        move    x:(r6+$c),a
        and     #>$007f00,a
        or      x0,a
        move    a1,x:(r7+$0a)
; TMOD (r6+$d bits 14..8): 0 SLEW, else FADE
        move    x:(r6+$d),a
        and     #>$007f00,a
        move    a1,x:(r3+$07)
; GLID (r6+$e bits 22..16): the glide one-poles' coefficient a call
        move    x:(r6+$e),a
        and     #>$7f0000,a
        move    a,x0
        move    #>$7f0000,a
        move    #>$0,x1
        sub     x0,a
        tlt     x1,a
        move    a,x0
        move    #>$155555,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$00213d,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$7fffff,a
        sub     x0,a
        move    a,x:(r3+$06)
; TIME -> left target, SKEW -> right target (A-units, held to the rings)
        move    x:(r6),a
        move    a,x0
        move    #>$7f0000,a
        move    #>$0,x1
        sub     x0,a
        tlt     x1,a
        move    a,x0
        move    #>$0e9cb4,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$7f7a00,y0
        mpy     y0,x0,a
        move    #>$7ff000,x0
        cmp     x0,a
        tgt     x0,a
        add     #>$100,a
        and     #>$fffe00,a  ; whole samples
        move    a,x:(r3+$09)
        move    x:(r6+$3),a
        move    a,x0
        move    #>$7f0000,a
        move    #>$0,x1
        sub     x0,a
        tlt     x1,a
        move    a,x0
        move    #>$080000,y0
        mpy     y0,x0,a
        bsr     >e2exp
        move    b,x0
        move    #>$7e9f06,y0
        mpy     y0,x0,a
        move    a,x0
        move    x:(r3+$09),y0
        mpy     y0,x0,a
        asl     a
        move    #>$7ff000,x0
        cmp     x0,a
        tgt     x0,a
        add     #>$100,a
        and     #>$fffe00,a
        move    a,x:(r3+$0a)
; MIX, SPRD (cross = 1 - width)
        move    x:(r6+$5),a
        move    #>$7f0000,x0
        cmp     x0,a
        blt     e2mset
        move    #>$7fffff,a
e2mset:
        move    a,x:(r7+$00)
        move    x:(r6+$4),a
        move    a,x0
        move    #>$7f0000,a
        move    #>$0,x1
        sub     x0,a
        tlt     x1,a
        move    a,x0
        move    #>$408102,y0
        mpy     y0,x0,a
        asl     a
        move    a,x:(r7+$02)
; SPRD glides once a call (2^-3)
        move    x:(r7+$02),a
        move    x:(r7+$03),b
        sub     b,a
        asr     #$3,a,a
        add     a,b
        move    b,x:(r7+$03)
        move    x:(r7+$00),a
        move    x:(r7+$01),b
        sub     b,a
        abs     a
        cmp     #>$000100,a
        bge     e2msnap
        move    x:(r7+$00),a
        move    a,x:(r7+$01)
e2msnap:
        move    x:(r7+$02),a
        move    x:(r7+$03),b
        sub     b,a
        abs     a
        cmp     #>$000100,a
        bge     e2wsnap
        move    x:(r7+$02),a
        move    a,x:(r7+$03)
e2wsnap:
; bounded clearing: 128 dry calls, 128 words of each ring a call; the heads snap to their targets
        move    x:(r3+$02),a
        tst     a
        beq     e2ready
        sub     #>$1,a
        move    a,x:(r3+$02)
        move    x:(r3+$09),a
        add     #>$100,a
        and     #>$fffe00,a
        move    a,x:(r7+$10)
        move    a,x:(r3+$10)
        move    a,x:(r3+$12)
        clr     a
        move    a,x:(r7+$11)
        move    a,x:(r3+$11)
        move    a,x:(r3+$13)
        move    a,x:(r7+$12)
        move    a,x:(r7+$13)
        move    a,x:(r3+$15)
        move    a,x:(r3+$16)
        move    a,x:(r7+$1b)
        move    a,x:(r7+$1d)
        move    x:(r3+$05),a
        move    a,x:(r7+$1c)
        move    x:(r3+$0a),a
        add     #>$100,a
        and     #>$fffe00,a
        move    a,x:(r7+$28)
        move    a,x:(r3+$18)
        move    a,x:(r3+$1a)
        clr     a
        move    a,x:(r7+$29)
        move    a,x:(r3+$19)
        move    a,x:(r3+$1b)
        move    a,x:(r7+$2a)
        move    a,x:(r7+$2b)
        move    a,x:(r3+$1d)
        move    a,x:(r3+$1e)
        move    a,x:(r7+$33)
        move    a,x:(r7+$35)
        move    x:(r3+$05),a
        move    a,x:(r7+$34)
        clr     a
        move    a,x:(r3+$04)
        move    a,x:(r7+$04)
        move    x:(r7+$02),a
        move    a,x:(r7+$03)
        move    x:(r3+$02),a
        cmp     #>$000080,a
        bge     e2noclry
        asl     #$7,a,a
        move    x:(r3+$00),x0
        add     x0,a
        move    a,r4
        move    #>$003fff,m4
        clr     a
        do      #128,>e2clry
        move    a,y:(r4)+
e2clry:
        nop     
        move    #>$ffffff,m4
e2noclry:
        move    x:(r3+$02),a
        cmp     #>$000080,a
        bge     e2noclrx
        asl     #$7,a,a
        add     #>$010000,a
        move    a,r4
        move    #>$003fff,m4
        clr     a
        do      #128,>e2clrx
        move    a,x:(r4)+
e2clrx:
        nop     
        move    #>$ffffff,m4
e2noclrx:
        rts     
e2ready:
; rider L: env = the block peak when higher (held one loop period), else released;
;   k/2 = min(RG, (0.29/2)/env); ramped over the call
        move    x:(r7+$1b),a
        move    x:(r3+$15),x0
        cmp     x0,a
        blt     e2nopk0
        move    a,x:(r3+$15)
        move    x:(r7+$10),b
        asr     #$d,b,b
        add     #>$2,b
        move    b1,x:(r3+$16)  ; hold = the delay in calls + 2
        bra     e2envd0
e2nopk0:
        move    x:(r3+$16),b
        tst     b
        ble     e2rel0
        sub     #>$1,b
        move    b,x:(r3+$16)
        bra     e2envd0
e2rel0:
        move    x:(r3+$15),x0
        move    #>$7fd865,y0
        mpy     y0,x0,a
        move    x:(r7+$1b),x0
        cmp     x0,a
        tlt     x0,a
        move    a,x:(r3+$15)
e2envd0:
        move    x:(r3+$15),a
        clr     b
        move    b,x:(r7+$1b)
        move    x:(r3+$05),b
        move    #>$128f5c,x0
        cmp     x0,a
        ble     e2kset0
        move    a,x0
        move    #>$128f5c,a
        bsr     >e2div
        move    x:(r3+$05),x0
        cmp     x0,b
        tgt     x0,b
e2kset0:
        move    x:(r7+$1c),x0
        sub     x0,b
        asr     #$4,b,b
        move    b,x:(r7+$1d)
; rider R: env = the block peak when higher (held one loop period), else released;
;   k/2 = min(RG, (0.29/2)/env); ramped over the call
        move    x:(r7+$33),a
        move    x:(r3+$1d),x0
        cmp     x0,a
        blt     e2nopk1
        move    a,x:(r3+$1d)
        move    x:(r7+$28),b
        asr     #$d,b,b
        add     #>$2,b
        move    b1,x:(r3+$1e)  ; hold = the delay in calls + 2
        bra     e2envd1
e2nopk1:
        move    x:(r3+$1e),b
        tst     b
        ble     e2rel1
        sub     #>$1,b
        move    b,x:(r3+$1e)
        bra     e2envd1
e2rel1:
        move    x:(r3+$1d),x0
        move    #>$7fd865,y0
        mpy     y0,x0,a
        move    x:(r7+$33),x0
        cmp     x0,a
        tlt     x0,a
        move    a,x:(r3+$1d)
e2envd1:
        move    x:(r3+$1d),a
        clr     b
        move    b,x:(r7+$33)
        move    x:(r3+$05),b
        move    #>$128f5c,x0
        cmp     x0,a
        ble     e2kset1
        move    a,x0
        move    #>$128f5c,a
        bsr     >e2div
        move    x:(r3+$05),x0
        cmp     x0,b
        tgt     x0,b
e2kset1:
        move    x:(r7+$34),x0
        sub     x0,b
        asr     #$4,b,b
        move    b,x:(r7+$35)
; ---- heads ----
        move    x:(r3+$04),a
        tst     a
        beq     e2nofade
        move    x:(r7+$04),a
        cmp     #>$7fffff,a
        blt     e2fstat
; fade complete: the new head becomes the current one
        move    x:(r3+$14),a
        move    a,x:(r7+$10)
        move    a,x:(r3+$10)
        move    a,x:(r3+$12)
        clr     a
        move    a,x:(r7+$11)
        move    a,x:(r3+$11)
        move    a,x:(r3+$13)
        move    x:(r3+$1c),a
        move    a,x:(r7+$28)
        move    a,x:(r3+$18)
        move    a,x:(r3+$1a)
        clr     a
        move    a,x:(r7+$29)
        move    a,x:(r3+$19)
        move    a,x:(r3+$1b)
        clr     a
        move    a,x:(r3+$04)
e2nofade:
        move    x:(r7+$0a),a
        tst     a
        bne     e2still
        move    x:(r3+$07),a
        tst     a
        beq     e2slew
; FADE mode, idle: the glides sit on the head; a target more than 1 % + 4 samples away starts a fade
        move    x:(r7+$10),a
        move    a,x:(r3+$10)
        move    a,x:(r3+$12)
        move    x:(r7+$11),a
        move    a,x:(r3+$11)
        move    a,x:(r3+$13)
        move    x:(r7+$28),a
        move    a,x:(r3+$18)
        move    a,x:(r3+$1a)
        move    x:(r7+$29),a
        move    a,x:(r3+$19)
        move    a,x:(r3+$1b)
        move    x:(r3+$09),a
        move    x:(r7+$10),x0
        sub     x0,a
        abs     a
        move    #>$0147ae,y0
        mpy     y0,x0,b
        add     #>$000800,b
        cmp     b,a
        bgt     e2fstart
        move    x:(r3+$0a),a
        move    x:(r7+$28),x0
        sub     x0,a
        abs     a
        move    #>$0147ae,y0
        mpy     y0,x0,b
        add     #>$000800,b
        cmp     b,a
        bgt     e2fstart
        bra     e2still
e2fstart:
        move    x:(r3+$09),a
        add     #>$100,a
        and     #>$fffe00,a
        move    a,x:(r3+$14)
        asr     #$9,a,a
        neg     a
        move    a1,x:(r7+$14)
        move    x:(r3+$0a),a
        add     #>$100,a
        and     #>$fffe00,a
        move    a,x:(r3+$1c)
        asr     #$9,a,a
        neg     a
        move    a1,x:(r7+$2c)
        clr     a
        move    a,x:(r7+$04)
        move    #>$1,a
        move    a,x:(r3+$04)
        bra     e2fstat
e2slew:
; SLEW: two one-poles (48 bit) toward the target; the head ramps to the second over the call
        move    x:(r3+$06),y0
        move    x:(r3+$09),a
        move    x:(r3+$10),b
        move    x:(r3+$11),b0
        sub     b,a
        move    a,x0
        mpy     y0,x0,a
        add     a,b
        move    b1,x:(r3+$10)
        move    b0,x:(r3+$11)
        move    x:(r3+$12),a
        move    x:(r3+$13),a0
        sub     a,b
        move    b,x0
        mpy     y0,x0,b
        add     b,a
        move    a1,x:(r3+$12)
        move    a0,x:(r3+$13)
; within 2/512 sample of the target: land on it
        move    x:(r3+$09),b
        sub     a,b
        abs     b
        cmp     #>$000002,b
        bge     e2gs0
        move    x:(r3+$09),a
        move    a,x:(r3+$10)
        move    a,x:(r3+$12)
        clr     a
        move    a,x:(r3+$11)
        move    a,x:(r3+$13)
e2gs0:
; inc = (S2 - D)/16; within 2/512 sample: the head lands on S2
        move    x:(r3+$12),a
        move    x:(r3+$13),a0
        move    x:(r7+$10),b
        move    x:(r7+$11),b0
        sub     b,a
        move    a1,b
        move    a0,b0
        abs     b
        cmp     #>$000002,b
        bge     e2gi0
        move    x:(r3+$12),x0
        move    x0,x:(r7+$10)
        move    x:(r3+$13),x0
        move    x0,x:(r7+$11)
        clr     a
e2gi0:
        asr     #$4,a,a
        move    a1,x:(r7+$12)
        move    a0,x:(r7+$13)
        move    x:(r3+$06),y0
        move    x:(r3+$0a),a
        move    x:(r3+$18),b
        move    x:(r3+$19),b0
        sub     b,a
        move    a,x0
        mpy     y0,x0,a
        add     a,b
        move    b1,x:(r3+$18)
        move    b0,x:(r3+$19)
        move    x:(r3+$1a),a
        move    x:(r3+$1b),a0
        sub     a,b
        move    b,x0
        mpy     y0,x0,b
        add     b,a
        move    a1,x:(r3+$1a)
        move    a0,x:(r3+$1b)
; within 2/512 sample of the target: land on it
        move    x:(r3+$0a),b
        sub     a,b
        abs     b
        cmp     #>$000002,b
        bge     e2gs1
        move    x:(r3+$0a),a
        move    a,x:(r3+$18)
        move    a,x:(r3+$1a)
        clr     a
        move    a,x:(r3+$19)
        move    a,x:(r3+$1b)
e2gs1:
; inc = (S2 - D)/16; within 2/512 sample: the head lands on S2
        move    x:(r3+$1a),a
        move    x:(r3+$1b),a0
        move    x:(r7+$28),b
        move    x:(r7+$29),b0
        sub     b,a
        move    a1,b
        move    a0,b0
        abs     b
        cmp     #>$000002,b
        bge     e2gi1
        move    x:(r3+$1a),x0
        move    x0,x:(r7+$28)
        move    x:(r3+$1b),x0
        move    x0,x:(r7+$29)
        clr     a
e2gi1:
        asr     #$4,a,a
        move    a1,x:(r7+$2a)
        move    a0,x:(r7+$2b)
        bra     e2mrun
e2still:
; frozen, or FADE idle: the head stands still
        clr     a
        move    a,x:(r7+$12)
        move    a,x:(r7+$13)
        move    a,x:(r7+$2a)
        move    a,x:(r7+$2b)
        bra     e2mrun
e2fstat:
; fading: the head stands still; its position once a call
        move    x:(r7+$10),a
        move    x:(r7+$11),a0
        move    a1,b
        move    a0,b0
        and     #>$0001ff,b
        asl     #$e,b,b
        move    b1,x0
        move    x0,x:(r7+$0b)
        asr     #$9,a,a
        sub     #>$1,a
        move    a1,x:(r7+$1e)
        move    #>$7fffff,b
        sub     x0,b
        move    b,y0
        mpy     y0,x0,b
        asl     b
        move    b,x:(r7+$0c)
        move    x:(r7+$0b),x0
        move    x0,x:(r7+$1f)
        move    x:(r7+$0c),x0
        move    x0,x:(r7+$20)
        move    x:(r7+$28),a
        move    x:(r7+$29),a0
        move    a1,b
        move    a0,b0
        and     #>$0001ff,b
        asl     #$e,b,b
        move    b1,x0
        move    x0,x:(r7+$0b)
        asr     #$9,a,a
        sub     #>$1,a
        move    a1,x:(r7+$36)
        move    #>$7fffff,b
        sub     x0,b
        move    b,y0
        mpy     y0,x0,b
        asl     b
        move    b,x:(r7+$0c)
        move    x:(r7+$0b),x0
        move    x0,x:(r7+$37)
        move    x:(r7+$0c),x0
        move    x0,x:(r7+$38)
        bsr     >e2regs
        bra     e2frun
e2mrun:
        bsr     >e2regs
        do      n7,>e2plend
        move    x:(r7+$00),a
        move    x:(r7+$01),b
        sub     b,a
        asr     #$7,a,a
        add     a,b
        move    b,x:(r7+$01)
; ======== left (Y ring) ========
        move    x:(r7+$10),a
        move    x:(r7+$11),a0
        move    x:(r7+$12),y1
